`timescale 1ns/1ps

/*
 * GENERATED BY CLAUDE OPUS 5.5
 * Self-checking testbench for sccb_writer.
 *
 * Contains a protocol-level SCCB slave model that only looks at the pins
 * (sio_c / sio_d), so it does not depend on the DUT's internal state machine.
 * It decodes START / bits / ACK / STOP and checks every 3-phase write:
 *
 *   - exactly one START and one STOP per transaction
 *   - exactly 3 bytes: 0x42 (slave ID + write), reg_addr, data
 *   - 27 SCL clocks (3 x 9), no stray bits
 *   - master releases SDA for every 9th (ACK / don't-care) bit
 *   - no bus contention (X on sio_d)
 *   - SDA never changes on the same cycle as an SCL edge
 *   - no SCL half-period shorter than HALF_PERIOD_CYCLES
 *   - reg_addr/data are latched on start (inputs scrambled after start)
 *   - start pulses while busy are ignored
 *   - bus returns to idle (both lines high) and stays quiet
 *   - busy is high during a write; new writes wait for !busy
 *
 * Writes sim/sccb_writer.vcd.  Run from fpga/:  make sim TB=sccb_writer
 */

module sccb_writer_tb;

    // ------------------------------------------------------------------
    // Parameters
    // ------------------------------------------------------------------
    localparam integer SYS_CLK_HZ = 100_000_000;     // DUT assumes 100 MHz
    localparam real    CLK_PERIOD = 1.0e9 / SYS_CLK_HZ;

    // Faster SCL than the real 200 kHz default so sim runs quickly.
    // The DUT math is the same; change back to 200_000 to sim real timing.
    localparam integer SCL_HZ     = 1_000_000;
    localparam integer HP         = SYS_CLK_HZ / SCL_HZ / 2;   // half period, in clk cycles

    // Slave pulls ACK low this many clk cycles after SCL falls.
    // The master must have released SDA by then (otherwise: contention / X).
    localparam integer ACK_DELAY  = (HP * 3) / 4;

    localparam [7:0]   SLAVE_ID   = 8'h42;
    localparam integer TIMEOUT    = 40 * 2 * HP;                // cycles per transaction
    localparam integer N_RANDOM   = 20;

    // ------------------------------------------------------------------
    // DUT
    // ------------------------------------------------------------------
    reg        clk = 0;
    reg        rst = 1;
    reg  [7:0] reg_addr = 0;
    reg  [7:0] data     = 0;
    reg        start    = 0;
    wire       sio_c;
    wire       sio_d;
    wire       busy;
    wire       ready;
    assign busy = ~ready;

    sccb_writer #(.CLK_FREQ(SCL_HZ)) dut (
        .clk(clk), .rst(rst),
        .sio_c(sio_c), .sio_d(sio_d),
        .reg_addr(reg_addr), .write_data(data), .valid(start), .ready(ready)
    );

    always #(CLK_PERIOD/2) clk = ~clk;

    // Open-drain bus: pull-up + slave can only pull low.
    pullup (sio_d);

    // ------------------------------------------------------------------
    // SCCB slave / protocol monitor
    // Samples on negedge clk (mid-cycle) so DUT outputs are settled.
    // ------------------------------------------------------------------
    localparam [1:0] ACK_IDLE = 0, ACK_WAIT = 1, ACK_DRIVE = 2, ACK_HIGH = 3;

    reg  [1:0] ack_state = ACK_IDLE;
    integer    ack_timer;

    // Slave holds ACK through the 9th clock and releases just after SCL falls.
    assign sio_d = (ack_state == ACK_DRIVE || ack_state == ACK_HIGH) ? 1'b0 : 1'bz;

    reg        pc, pd;            // previous sampled SCL / SDA
    reg        c, d;              // current sampled SCL / SDA
    reg        in_txn;
    integer    bit_cnt;           // bits of the current byte (0..8)
    integer    byte_cnt;
    reg  [7:0] shreg;
    reg  [7:0] rx [0:15];

    // per-transaction stats (reset on START)
    integer    scl_rises;
    integer    acks_ok;
    integer    proto_errs;        // contention, early ACK, simultaneous edges, ...
    integer    gap, min_gap;      // clk cycles between SCL edges
    reg        scl_edge_seen;     // skip START->first edge (that's START hold, not a half period)

    // totals
    integer    starts_seen = 0;
    integer    stops_seen  = 0;

    // results of the last finished transaction (latched on STOP)
    integer    last_bytes, last_stray, last_rises, last_acks, last_errs, last_min_gap;
    reg  [7:0] last_rx [0:15];

    integer    k;

    always @(negedge clk) begin
        if (rst) begin
            pc = 1; pd = 1;
            in_txn = 0; bit_cnt = 0; byte_cnt = 0;
            ack_state <= ACK_IDLE;
            gap = 0;
        end else begin
            c = sio_c;
            d = sio_d;
            gap = gap + 1;

            if (d === 1'bx) begin
                $display("[%0t] PROTO ERROR: bus contention on sio_d (X)", $time);
                proto_errs = proto_errs + 1;
            end

            if (c !== pc && d !== pd && in_txn) begin
                $display("[%0t] PROTO ERROR: sio_d changed on the same cycle as an sio_c edge", $time);
                proto_errs = proto_errs + 1;
            end

            // ---- START: SDA falls while SCL high
            if (c === 1 && pc === 1 && pd === 1 && d === 0) begin
                if (in_txn) begin
                    $display("[%0t] PROTO ERROR: repeated START inside a transaction", $time);
                    proto_errs = proto_errs + 1;
                end else begin
                    proto_errs = 0;
                end
                starts_seen = starts_seen + 1;
                in_txn    = 1;
                bit_cnt   = 0;
                byte_cnt  = 0;
                scl_rises = 0;
                acks_ok   = 0;
                min_gap   = 32'h7fff_ffff;
                gap       = 0;
                scl_edge_seen = 0;
                ack_state <= ACK_IDLE;
            end

            // ---- STOP: SDA rises while SCL high
            else if (c === 1 && pc === 1 && pd === 0 && d === 1 && in_txn) begin
                stops_seen   = stops_seen + 1;
                in_txn       = 0;
                // The SCL rise that precedes STOP (SDA low) is part of the
                // STOP condition, not a data bit.
                if (bit_cnt > 0) begin
                    bit_cnt   = bit_cnt - 1;
                    scl_rises = scl_rises - 1;
                end
                last_bytes   = byte_cnt;
                last_stray   = bit_cnt;
                last_rises   = scl_rises;
                last_acks    = acks_ok;
                last_errs    = proto_errs;
                last_min_gap = min_gap;
                for (k = 0; k < 16; k = k + 1) last_rx[k] = rx[k];
                ack_state <= ACK_IDLE;
            end

            // ---- SCL rising edge: sample a bit
            else if (pc === 0 && c === 1 && in_txn) begin
                scl_rises = scl_rises + 1;
                if (scl_edge_seen && gap < min_gap) min_gap = gap;
                scl_edge_seen = 1;
                gap = 0;

                if (bit_cnt < 8) begin
                    shreg   = {shreg[6:0], d};
                    bit_cnt = bit_cnt + 1;
                    if (bit_cnt == 8 && byte_cnt < 16) rx[byte_cnt] = shreg;
                end else begin
                    // 9th clock: ACK / don't-care bit
                    if (ack_state != ACK_DRIVE) begin
                        $display("[%0t] PROTO ERROR: SCL low phase too short for slave ACK", $time);
                        proto_errs = proto_errs + 1;
                    end else if (d === 1'b0) begin
                        acks_ok = acks_ok + 1;
                    end else begin
                        $display("[%0t] PROTO ERROR: master did not release sio_d for ACK (saw %b)", $time, d);
                        proto_errs = proto_errs + 1;
                    end
                    ack_state <= ACK_HIGH;
                    byte_cnt   = byte_cnt + 1;
                    bit_cnt    = 0;
                end
            end

            // ---- SCL falling edge
            else if (pc === 1 && c === 0 && in_txn) begin
                if (scl_edge_seen && gap < min_gap) min_gap = gap;
                scl_edge_seen = 1;
                gap = 0;
                if (bit_cnt == 8) begin
                    ack_state <= ACK_WAIT;    // start ACK countdown
                    ack_timer  = ACK_DELAY;
                end else begin
                    ack_state <= ACK_IDLE;    // (already released combinationally)
                end
            end

            // ---- ACK countdown
            if (ack_state == ACK_WAIT) begin
                if (ack_timer <= 0) ack_state <= ACK_DRIVE;
                else                ack_timer = ack_timer - 1;
            end

            pc = c;
            pd = d;
        end
    end

    // ------------------------------------------------------------------
    // Test helpers
    // ------------------------------------------------------------------
    integer errors = 0;
    integer tests  = 0;

    task fail(input [8*80-1:0] msg);
        begin
            $display("[%0t]   FAIL: %0s", $time, msg);
            errors = errors + 1;
        end
    endtask

    task wait_for_stop(input integer stops_before, output reg timed_out);
        integer n;
        begin
            n = 0;
            while (stops_seen == stops_before && n < TIMEOUT) begin
                @(posedge clk);
                n = n + 1;
            end
            timed_out = (stops_seen == stops_before);
        end
    endtask

    // Check the last finished transaction against expected addr/data
    task check_txn(input [7:0] exp_addr, input [7:0] exp_data);
        integer e0;
        begin
            e0 = errors;
            if (last_bytes != 3) begin
                $display("    expected 3 bytes, got %0d (+%0d stray bits)", last_bytes, last_stray);
                fail("wrong number of bytes");
            end else begin
                if (last_rx[0] !== SLAVE_ID) begin
                    $display("    byte0: expected %02h got %02h", SLAVE_ID, last_rx[0]);
                    fail("bad slave ID byte");
                end
                if (last_rx[1] !== exp_addr) begin
                    $display("    byte1: expected %02h got %02h", exp_addr, last_rx[1]);
                    fail("bad reg_addr byte");
                end
                if (last_rx[2] !== exp_data) begin
                    $display("    byte2: expected %02h got %02h", exp_data, last_rx[2]);
                    fail("bad data byte");
                end
            end
            if (last_stray != 0)  fail("stray bits before STOP");
            if (last_rises != 27) begin
                $display("    expected 27 SCL clocks, got %0d", last_rises);
                fail("wrong SCL clock count");
            end
            if (last_acks != 3)   fail("master did not release SDA for all 3 ACK bits");
            if (last_errs != 0)   fail("protocol errors during transaction (see above)");
            if (last_rises > 1 && last_min_gap < HP) begin
                $display("    shortest SCL half-period: %0d clk (min %0d)", last_min_gap, HP);
                fail("SCL too fast");
            end
            if (errors == e0)
                $display("[%0t]   ok   addr=%02h data=%02h", $time, exp_addr, exp_data);
        end
    endtask

    // Full write: pulse start, scramble inputs, wait for STOP, check.
    task do_write(input [7:0] a, input [7:0] dv);
        integer s0;
        reg     to;
        begin
            tests = tests + 1;
            s0 = stops_seen;
            while (busy) @(posedge clk);   // controller waits for !busy
            @(posedge clk);
            reg_addr <= a;
            data     <= dv;
            start    <= 1;
            @(posedge clk);
            start    <= 0;
            reg_addr <= ~a;            // DUT must have latched the values
            data     <= ~dv;
            wait_for_stop(s0, to);
            if (to) fail("timeout waiting for STOP");
            else    check_txn(a, dv);
        end
    endtask

    task check_idle(input integer cycles);
        integer n, s0;
        begin
            s0 = starts_seen;
            for (n = 0; n < cycles; n = n + 1) begin
                @(negedge clk);
                if (sio_c !== 1'b1 || sio_d !== 1'b1) begin
                    $display("[%0t]   bus not idle: sio_c=%b sio_d=%b", $time, sio_c, sio_d);
                    fail("bus not idle");
                    n = cycles;
                end
            end
            if (starts_seen != s0) fail("unexpected START while idle");
        end
    endtask

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    integer    i, s0, seed;
    reg        to;
    reg  [7:0] ra, rd;

    initial begin
        $dumpfile("sim/sccb_writer.vcd");
        $dumpvars(0, sccb_writer_tb);

        $display("SCL = %0d Hz, half period = %0d clk", SCL_HZ, HP);

        // ---- reset
        repeat (5) @(posedge clk);
        rst <= 0;
        repeat (2) @(posedge clk);

        $display("\n== Idle after reset");
        tests = tests + 1;
        check_idle(4 * HP);

        // ---- directed writes
        $display("\n== Directed writes");
        do_write(8'h12, 8'h80);   // COM7 reset, typical first OV7670 write
        do_write(8'h00, 8'h00);
        do_write(8'hFF, 8'hFF);
        do_write(8'hA5, 8'h5A);
        do_write(8'h3A, 8'h04);

        $display("\n== Idle after writes");
        tests = tests + 1;
        check_idle(4 * HP);

        // ---- start while busy must be ignored
        $display("\n== Start while busy is ignored");
        tests = tests + 1;
        s0 = stops_seen;
        while (busy) @(posedge clk);
        @(posedge clk); reg_addr <= 8'h11; data <= 8'h22; start <= 1;
        @(posedge clk); start <= 0;
        i = 0;                                        // wait until mid-transaction
        while (!(in_txn && byte_cnt == 1) && i < TIMEOUT) begin
            @(posedge clk); i = i + 1;
        end
        if (i == TIMEOUT) $display("    (never reached byte 1, poking start anyway)");
        @(posedge clk); reg_addr <= 8'hEE; data <= 8'hDD; start <= 1;
        @(posedge clk); start <= 0;
        wait_for_stop(s0, to);
        if (to) fail("timeout waiting for STOP");
        else    check_txn(8'h11, 8'h22);
        check_idle(4 * HP);
        if (stops_seen != s0 + 1) fail("extra transaction after start-while-busy");

        // ---- random writes
        $display("\n== Random writes");
        seed = 32'h5CCB;
        for (i = 0; i < N_RANDOM; i = i + 1) begin
            ra = $random(seed);
            rd = $random(seed);
            do_write(ra, rd);
        end

        // ---- summary
        $display("\n========================================");
        if (errors == 0) $display(" PASS  (%0d tests, %0d transactions)", tests, stops_seen);
        else             $display(" FAIL  (%0d errors, %0d tests)", errors, tests);
        $display("========================================\n");
        $finish;
    end

    // global watchdog
    initial begin
        #(CLK_PERIOD * TIMEOUT * (N_RANDOM + 20));
        $display("GLOBAL TIMEOUT");
        $finish;
    end

endmodule